import React, { useState } from "react";
import axios from "axios";

function App() {
   const [file, setFile] = useState(null);
    const [threshold, setThreshold] = useState(0.5);
    const [results, setResults] = useState([]);

    // Gestion du CSV
    const handleFileChange = (e) => {
      setFile(e.target.files[0]);
    };

    // Soumission au backend
    const handleSubmit = async () => {
      if (!file) return alert("Veuillez sélectionner un fichier CSV");

      const formData = new FormData();
      formData.append("file", file);
      formData.append("threshold", threshold);

      try {
        const res = await axios.post("http://127.0.0.1:8000/predict_csv", formData, {
          headers: { "Content-Type": "multipart/form-data" },
        });

        if (res.data.error) {
          alert(res.data.error);
        } else {
          setResults(res.data.results);
        }
      } catch (err) {
        console.error(err);
        alert("Erreur lors de la prédiction");
      }
    };

    return (
      <div style={{ padding: "2rem" }}>
        <h1>Détection de Fraude (CSV)</h1>

        {/* Upload CSV */}
        <div>
          <input type="file" accept=".csv" onChange={handleFileChange} />
        </div>

        {/* Seuil de décision */}
        <div style={{ marginTop: "1rem" }}>
          <label>Seuil de décision: </label>
          <input
            type="number"
            step="0.01"
            min="0"
            max="1"
            value={threshold}
            onChange={(e) => setThreshold(parseFloat(e.target.value))}
          />
        </div>

        {/* Bouton prédiction */}
        <div style={{ marginTop: "1rem" }}>
          <button onClick={handleSubmit}>Prédire</button>
        </div>

        {/* Affichage des résultats */}
        {results.length > 0 && (
          <div style={{ marginTop: "2rem" }}>
            <h2>Résultats :</h2>
            <table border="1" cellPadding="5">
              <thead>
                <tr>
                  <th>#</th>
                  <th>Probabilité</th>
                  <th>Prédiction</th>
                </tr>
              </thead>
              <tbody>
                {results.map((r, i) => (
                  <tr key={i}>
                    <td>{i + 1}</td>
                    <td>{r.probability}</td>
                    <td
                      style={{
                        color: r.prediction === "Fraude" ? "red" : "green",
                        fontWeight: "bold",
                      }}
                    >
                      {r.prediction}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    );
}

export default App;
